WITH department_totals AS (SELECT dept_id, SUM(CASE WHEN level = 'L3' THEN 1 ELSE 0 END) AS l3_count, SUM(salary) AS total_salary FROM employees GROUP BY dept_id) SELECT departments.id, departments.dept_name, department_totals.l3_count, department_totals.total_salary FROM departments LEFT JOIN department_totals ON departments.id = department_totals.dept_id WHERE department_totals.total_salary > 348000
